1: """Flash builds of the firmware in turn and compare their serial logs.
2: 
3:     .venv/bin/python -I tools/ab_flash.py --hack CubicGrid --seconds 60 \\
4:         --rounds 2 --out /tmp/ab base= iram=-DGL_IRAM "prof=-DGL_PROFILE -DGL_IRAM"
5: 
6: Each `name=flags` is a variant. Every variant is built once, pinned to the
7: hack with rotation off (`START_HACK`, `ROTATE_SECONDS=0`), and its image kept.
8: Then, round by round, each image is flashed and the serial log captured for
9: `--seconds`. A boot is deterministic, so alternating builds and comparing
10: window by window is how this repo measures a change (AGENTS.md).
11: 
12: This flashes the device: run it only with Rod's go-ahead. It never touches
13: the partition table or `ffat`; `pio run -t upload` writes what a normal
14: upload writes.
15: """
16: 
17: import argparse
18: import os
19: import re
20: import statistics
21: import subprocess
22: import sys
23: from dataclasses import dataclass, field
24: from pathlib import Path
25: 
26: ROOT = Path(__file__).resolve().parent.parent
27: FIRMWARE = ROOT / "firmware"
28: 
29: RUN = re.compile(r"^run (?P<hack>\S+) (?P<fields>.*)$")
30: GLPROF = re.compile(r"^glprof (?P<hack>\S+) (?P<fields>.*)$")
31: FIELD = re.compile(r"(\w+)=([-\d.]+)")
32: 
33: 
34: def parse_fields(text: str) -> dict[str, float]:
35:     """`fps=12.3 step=45.6ms rows=466` to {"fps": 12.3, "step": 45.6, ...}."""
36:     return {k: float(v) for k, v in FIELD.findall(text)}
37: 
38: 
39: @dataclass
40: class Capture:
41:     runs: list[dict[str, float]] = field(default_factory=list)
42:     glprof: list[dict[str, float]] = field(default_factory=list)
43: 
44: 
45: def parse_log(text: str, hack: str) -> Capture:
46:     """The `run` and `glprof` windows a log has for `hack` (any case)."""
47:     out = Capture()
48:     for raw in text.splitlines():
49:         line = raw.strip()
50:         for pattern, bucket in ((RUN, out.runs), (GLPROF, out.glprof)):
51:             m = pattern.match(line)
52:             if m and m.group("hack").lower() == hack.lower():
53:                 bucket.append(parse_fields(m.group("fields")))
54:     return out
55: 
56: 
57: def summarise(windows: list[dict[str, float]], skip: int = 1) -> dict[str, float]:
58:     """Mean of each field, leaving out the first `skip` windows: the first
59:     holds the boot and, for push, the name overlay (AGENTS.md)."""
60:     kept = windows[skip:]
61:     if not kept:
62:         return {}
63:     keys = sorted({k for w in kept for k in w})
64:     return {k: statistics.fmean(w[k] for w in kept if k in w) for k in keys}
65: 
66: 
67: def render(results: dict[str, list[Capture]], keys: list[str]) -> str:
68:     lines = [
69:         "| Variant | Round | Windows | " + " | ".join(keys) + " |",
70:         "| --- | --- | --- | " + " | ".join("---" for _ in keys) + " |",
71:     ]
72:     for name, captures in results.items():
73:         for i, cap in enumerate(captures, 1):
74:             merged = summarise(cap.runs)
75:             merged.update(summarise(cap.glprof))
76:             cells = [f"{merged[k]:.2f}" if k in merged else "-" for k in keys]
77:             lines.append(
78:                 f"| {name} | {i} | {max(len(cap.runs) - 1, 0)} | "
79:                 + " | ".join(cells)
80:                 + " |"
81:             )
82:     return "\n".join(lines) + "\n"
83: 
84: 
85: def pio(*args: str, flags: str, build_dir: Path) -> subprocess.CompletedProcess:
86:     """`pio run` for the stopwatch. Each variant has its own `build_dir`:
87:     PlatformIO cleans a build directory, image and all, when the flags it
88:     was built with change, so variants sharing one wipe each other."""
89:     env = {
90:         **os.environ,
91:         "PLATFORMIO_CORE_DIR": str(ROOT / ".platformio"),
92:         "PLATFORMIO_BUILD_DIR": str(build_dir),
93:         "NO_COLOR": "1",
94:         "PLATFORMIO_BUILD_FLAGS": flags,
95:     }
96:     return subprocess.run(
97:         [
98:             str(ROOT / ".venv" / "bin" / "pio"),
99:             "run",
100:             "-d",
101:             str(FIRMWARE),
102:             "-e",
103:             "stopwatch",
104:             *args,
105:         ],
106:         env=env,
107:         capture_output=True,
108:         text=True,
109:         check=False,
110:     )
111: 
112: 
113: def pinned(hack: str, flags: str) -> str:
114:     return f'-DSTART_HACK=\\"{hack}\\" -DROTATE_SECONDS=0 {flags}'.strip()
115: 
116: 
117: def build(name: str, flags: str, out: Path) -> None:
118:     result = pio(flags=flags, build_dir=out / f"pio-{name}")
119:     (out / f"build-{name}.log").write_text(result.stdout + result.stderr)
120:     if result.returncode != 0:
121:         sys.exit(f"build of {name} failed; see {out / f'build-{name}.log'}")
122: 
123: 
124: def flash(name: str, flags: str, out: Path, log: Path) -> None:
125:     """Upload the image `build` made, without rebuilding."""
126:     build_dir = out / f"pio-{name}"
127:     result = pio("-t", "nobuild", "-t", "upload", flags=flags, build_dir=build_dir)
128:     log.write_text(result.stdout + result.stderr)
129:     if result.returncode != 0 or "Hash of data verified" not in result.stdout:
130:         sys.exit(f"flash of {name} did not verify; see {log}")
131: 
132: 
133: def main(argv: list[str]) -> int:
134:     parser = argparse.ArgumentParser(description=__doc__.split("\n")[0])
135:     parser.add_argument("--hack", required=True, help="a name from g_hacks[]")
136:     parser.add_argument("--seconds", type=float, default=60)
137:     parser.add_argument("--rounds", type=int, default=2)
138:     parser.add_argument("--out", type=Path, required=True)
139:     parser.add_argument("--keys", default="fps,step,push,rows")
140:     parser.add_argument("variants", nargs="+", help="name=flags")
141:     args = parser.parse_args(argv)
142:     sys.path.insert(0, str(ROOT / "tools"))
143:     import serial_capture
144: 
145:     args.out.mkdir(parents=True, exist_ok=True)
146:     variants = {
147:         name: pinned(args.hack, flags)
148:         for name, flags in (v.split("=", 1) for v in args.variants)
149:     }
150:     for name, flags in variants.items():
151:         build(name, flags, args.out)
152:     results: dict[str, list[Capture]] = {name: [] for name in variants}
153:     for r in range(1, args.rounds + 1):
154:         for name, flags in variants.items():
155:             flash(name, flags, args.out, args.out / f"flash-{r}-{name}.log")
156:             log = args.out / f"serial-{r}-{name}.log"
157:             serial_capture.capture(str(log), args.seconds)
158:             results[name].append(parse_log(log.read_text(errors="replace"), args.hack))
159:     table = render(results, args.keys.split(","))
160:     (args.out / "summary.md").write_text(table)
161:     print(table, end="")
162:     return 0
163: 
164: 
165: if __name__ == "__main__":
166:     raise SystemExit(main(sys.argv[1:]))

