873: static uint16_t alone(float r, float g, float b, int flat) {
874:   open_line_scene(0);
875:   glShadeModel(flat ? GL_FLAT : GL_SMOOTH);
876:   fill_everything_with(r, g, b, 0);
877:   return centre_pixel();
878: }
