880: static uint16_t added(float r1, float g1, float b1, float r2, float g2, float b2,
881:                       GLenum sfactor, int flat) {
882:   open_line_scene(0);
883:   glShadeModel(flat ? GL_FLAT : GL_SMOOTH);
884:   fill_everything_with(r1, g1, b1, 0);
885:   glEnable(GL_BLEND);
886:   glBlendFunc(sfactor, GL_ONE);
887:   fill_everything_with(r2, g2, b2, 0);
888:   return centre_pixel();
889: }
