1023: /* Polygon offset. A second fill at exactly the same depth wins a tie, since
1024:  * TinyGL's test is >=. With the offset enabled it is pushed back and loses. */
1025: static uint16_t second_fill_behind_the_first(int enable, float factor, float units,
1026:                                              float z_slope, float back) {
1027:   open_line_scene(0);
1028:   glEnable(GL_DEPTH_TEST);
1029:   glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);
1030:   for (int pass = 0; pass < 2; pass++) {
1031:     if (pass == 1) {
1032:       glPolygonOffset(factor, units);
1033:       if (enable) glEnable(GL_POLYGON_OFFSET_FILL);
1034:     }
1035:     glColor3f(pass ? 1.0f : 0.0f, pass ? 0.0f : 1.0f, 0);
1036:     glBegin(GL_TRIANGLES);
1037:     const float z = pass ? back : 0.0f;
1038:     glVertex3f(-1, -1, -z_slope + z);
1039:     glVertex3f(3, -1, z_slope * 3 + z);
1040:     glVertex3f(-1, 3, -z_slope + z);
1041:     glEnd();
1042:   }
1043:   const uint16_t result = centre_pixel();
1044:   glshim_close();
1045:   return result;
1046: }
1047: 
1048: static uint16_t second_fill_over_the_first(int enable, float factor, float units,
1049:                                            float z_slope) {
1050:   return second_fill_behind_the_first(enable, factor, units, z_slope, 0.0f);
1051: }
