857: /* Additive blending (GL_ONE, GL_ONE; and GL_SRC_ALPHA, GL_ONE, since TinyGL
858:  * has no alpha) adds each channel of the canvas's byte-swapped RGB565 and
859:  * saturates it on its own (issue #73). TinyGL's own blend decoded the swapped
860:  * pixel as unswapped, which was right only for black and white. */
861: static uint16_t unswap(uint16_t v) { return (uint16_t)((v << 8) | (v >> 8)); }
862: 
863: static uint16_t saturating_sum(uint16_t a, uint16_t b) {
864:   const unsigned x = unswap(a), y = unswap(b);
865:   unsigned r = (x >> 11) + (y >> 11), g = ((x >> 5) & 63) + ((y >> 5) & 63),
866:            bl = (x & 31) + (y & 31);
867:   if (r > 31) r = 31;
868:   if (g > 63) g = 63;
869:   if (bl > 31) bl = 31;
870:   return unswap((uint16_t)((r << 11) | (g << 5) | bl));
871: }
