915: /* Half resolution (issue #43, for Hypnowheel): at scale 2 TinyGL draws into a
916:  * half-size buffer, glViewport is halved to match, and the swap doubles each
917:  * pixel into the canvas. A smooth three-colour triangle comes out in 2 by 2
918:  * blocks only if pixels really are doubled. */
919: static void corner_triangle_frame(float x0, float y0) {
920:   glViewport(0, 0, SIZE, SIZE);
921:   glMatrixMode(GL_PROJECTION);
922:   glLoadIdentity();
923:   glMatrixMode(GL_MODELVIEW);
924:   glLoadIdentity();
925:   glClearColor(0, 0, 0, 0);
926:   glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);
927:   glBegin(GL_TRIANGLES);
928:   glColor3f(1, 0, 0);
929:   glVertex3f(x0, y0, 0);
930:   glColor3f(0, 1, 0);
931:   glVertex3f(1, y0, 0);
932:   glColor3f(0, 0, 1);
933:   glVertex3f(x0, 1, 0);
934:   glEnd();
935: }
