1110: /* A line on the edge of its own opaque polygon, as in Unknown Pleasures: each
1111:  * row is a smooth line drawn over the top edge of a black quad on a plane that
1112:  * tilts away from the viewer, with the offset the hack asks for. TinyGL snaps
1113:  * the quad's vertices to whole pixels, so as the pair drifts the quad's depth
1114:  * at the line's pixels moves by up to a pixel's worth of slope, and the quad
1115:  * ate parts of its line. */
1116: static double line_brightness_on_its_quad(float shift, float tilt) {
1117:   open_line_scene(1);
1118:   glEnable(GL_DEPTH_TEST);
1119:   glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);
1120:   glEnable(GL_POLYGON_OFFSET_FILL);
1121:   glPolygonOffset(0.5f, 0.5f);
1122:   const float top = 0.1f + shift, depth = 0.3f;
1123:   glColor3f(1, 1, 1);
1124:   glBegin(GL_LINE_STRIP);
1125:   glVertex3f(-0.7f, top, depth);
1126:   glVertex3f(0.7f, top, depth);
1127:   glEnd();
1128:   glColor3f(0, 0, 0);
1129:   glBegin(GL_QUAD_STRIP);
1130:   glVertex3f(-0.7f, top, depth);
1131:   glVertex3f(-0.7f, top - 0.4f, depth - 0.4f * tilt);
1132:   glVertex3f(0.7f, top, depth);
1133:   glVertex3f(0.7f, top - 0.4f, depth - 0.4f * tilt);
1134:   glEnd();
1135:   double total, centroid;
1136:   measure_line(0, &total, &centroid);
1137:   glshim_close();
1138:   return total;
1139: }
