1141: void test_a_smooth_line_is_not_eaten_by_its_own_polygon_as_they_drift(void) {
1142:   const float tilts[] = {0.5f, 1.0f, 2.0f};
1143:   for (int t = 0; t < 3; t++) {
1144:     double best = 0, worst = 1e30;
1145:     for (int k = 0; k < 16; k++) {
1146:       const double b = line_brightness_on_its_quad(k * 0.0625f * PIXEL_NDC, tilts[t]);
1147:       if (b > best) best = b;
1148:       if (b < worst) worst = b;
1149:     }
1150:     TEST_ASSERT_TRUE_MESSAGE(best > 0, "nothing drawn");
"}]}

