125: static GLint ClipLine1(GLfloat denom, GLfloat num, GLfloat* tmin, GLfloat* tmax) {
126: 	GLfloat t;
127: 
128: 	if (denom > 0) {
129: 		t = num / denom;
130: 		if (t > *tmax)
131: 			return 0;
132: 		if (t > *tmin)
133: 			*tmin = t;
134: 	} else if (denom < 0) {
135: 		t = num / denom;
136: 		if (t < *tmin)
137: 			return 0;
138: 		if (t < *tmax)
139: 			*tmax = t;
140: 	} else if (num > 0)
141: 		return 0;
142: 	return 1;
143: }
